svg.script:
(async () => {
  const base = location.href.replace(/[?#].*$/, "").replace(/[^/]*$/, "");
  const msg = document.getElementById("msg");
  try {
    const res = await fetch(base + "index.html", { cache: "no-cache" });
    if (!res.ok) throw new Error("HTTP " + res.status);
    let html = await res.text();
    html = html.replace(/<head([^>]*)>/i, '<head$1><base href="' + base + '">');
    const frame = document.createElementNS("http://www.w3.org/1999/xhtml", "iframe");
    frame.setAttribute("allow", "fullscreen; autoplay; gamepad; pointer-lock");
    frame.setAttribute("allowfullscreen", "");
    document.getElementById("root").appendChild(frame);
    // Write the page into a blank frame so it keeps this real https:// address (games need it)
    const doc = frame.contentDocument;
    doc.open();
    doc.write(html);
    doc.close();
    msg.remove();
    frame.contentWindow.focus();
  } catch (err) {
    msg.textContent = "Couldn't load the site (" + err.message + "). Try refreshing.";
  }
})();
